--
-- Estructura de tabla para la tabla `invoices`
--

CREATE TABLE `invoices` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `number` varchar(255) NOT NULL,
  `document_type` varchar(255) DEFAULT NULL,
  `client_id` bigint(20) NOT NULL,
  `date` date NOT NULL,
  `total` decimal(10,2) NOT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'Emitida',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `electronic_invoice_provider` varchar(255) DEFAULT NULL,
  `electronic_invoice_status` varchar(255) DEFAULT NULL,
  `electronic_invoice_external_id` varchar(255) DEFAULT NULL,
  `electronic_invoice_series` varchar(255) DEFAULT NULL,
  `electronic_invoice_number` varchar(255) DEFAULT NULL,
  `electronic_invoice_file_name` varchar(255) DEFAULT NULL,
  `electronic_invoice_pdf_ticket_url` text DEFAULT NULL,
  `electronic_invoice_pdf_a4_url` text DEFAULT NULL,
  `electronic_invoice_xml_url` text DEFAULT NULL,
  `electronic_invoice_cdr_url` text DEFAULT NULL,
  `electronic_invoice_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`electronic_invoice_response`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `invoice_sale`
--

CREATE TABLE `invoice_sale` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `invoice_id` bigint(20) UNSIGNED NOT NULL,
  `sale_id` bigint(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `loan_payments`
--

CREATE TABLE `loan_payments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `bank_loan_id` bigint(20) UNSIGNED NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `payment_method_id` bigint(20) UNSIGNED DEFAULT NULL,
  `payment_date` date NOT NULL,
  `installment_number` int(11) DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

